<script setup>
import {ref,onMounted,computed} from 'vue';import {ClockIcon} from '@heroicons/vue/24/outline';import {parentApi} from '../../services/parentApi';import {useParentPortal} from '../../composables/useParentPortal'
const {parentId}=useParentPortal();const rows=ref([]),loading=ref(true),error=ref('');const grouped=computed(()=>rows.value);onMounted(async()=>{try{const r=await parentApi.getSchedule(parentId.value);rows.value=r.data||[]}catch(e){error.value=e.message}finally{loading.value=false}})
</script>
<template><div class="space-y-6"><div class="card p-5"><h3 class="font-display font-semibold mb-4 flex items-center gap-2"><ClockIcon class="w-5 h-5 text-brand-blue"/> Family Schedule</h3><p v-if="loading">Loading schedule...</p><p v-else-if="error" class="text-red-500">{{error}}</p><div v-else-if="!grouped.length" class="text-slate-500">No booked sessions for your children.</div><div v-else class="space-y-3"><div v-for="s in grouped" :key="`${s.student_id}-${s.session_id}`" class="rounded-xl border p-4"><p class="font-semibold">{{s.student_name}} · {{s.subject}}</p><p class="text-sm text-slate-500">{{s.date}} · {{s.start_time}}–{{s.end_time}} · {{s.tutor}}</p><p class="text-xs text-slate-500">{{s.status}}</p><a v-if="(s.status === 'Scheduled' || s.status === 'Rescheduled') && (s.meeting_url || s.meetingUrl)" :href="s.meeting_url || s.meetingUrl" target="_blank" rel="noopener noreferrer" class="btn grad sm inline-flex items-center justify-center mt-3">Join Meeting</a></div></div></div></div></template>
